/*
    Shared catalogue rows for AyurvedicClinicMgmt - menus, screens, sections, fields.
    Generated 2026-11-17 20:57 from . by Export-SharedCatalogue.ps1.

    Run AFTER baseline-schema.sql and BEFORE provisioning the first clinic.
    Provisioning grants access against these rows; it does not create them, so a
    clinic provisioned without them gets a login and an empty menu.

    Only tables without tenant_id are here, so this file holds no clinic data.
    Each table is skipped if it already has rows, so re-running is safe.
*/
SET NOCOUNT ON;
SET XACT_ABORT ON;
GO

------------------------------------------------------------------ menus (32 rows)
IF NOT EXISTS (SELECT 1 FROM dbo.[menus])
BEGIN
    SET IDENTITY_INSERT dbo.[menus] ON;
    SET IDENTITY_INSERT dbo.[menus] OFF;
    PRINT '  menus seeded';
END
ELSE PRINT '  menus already has rows - left alone';
GO

